import { createEffect, createSignal, mergeProps, type Component } from "solid-js";

import { Icon } from "#core/ui-next/components/icon.jsx";
import { ComponentRegistry } from "#core/ui-next/services/component-registry.js";
import { spacing } from "#core/ui-next/utilities/spacing.js";

import { Activatable, ActivatableProps } from "./activatable";

export interface ImageButtonProps extends ActivatableProps {
	imageData: {
		base: string;
		focus: string;
		active?: string;
		disabled?: string;
	};
	size?: spacing;
}
const ImageButtonComponent: Component<ImageButtonProps> = (props) => {
	const [mergedProps, setMergedProps] = createSignal<ImageButtonProps>({
		imageData: { base: "", focus: "" },
		size: "12",
	});

	createEffect(() => {
		const audioObject = props.audio ?? {};
		audioObject.onPress ??= "data-audio-primary-button-press";
		audioObject.onFocus ??= "data-audio-primary-button-focus";

		const defaultProps: ImageButtonProps = { audio: audioObject, imageData: { base: "", focus: "" }, size: "12" };
		const finalPropsObject = mergeProps(defaultProps, props);

		setMergedProps(finalPropsObject);
	});

	return (
		<Activatable
			{...mergedProps()}
			class={`fxs-image-button relative size-${props.size} ${props.class ?? ""}`}
			classList={{
				"opacity-50": props.disabled && !props.imageData.disabled,
			}}
			name={props.name ? props.name + "(ImageButton)" : "ImageButton"}
		>
			<Icon
				class="absolute inset-0 size-full"
				name={props.imageData.base}
				isUrl
			/>
			<Icon
				class="absolute inset-0 size-full opacity-0 fxs-image-button__bg--focus"
				name={props.imageData.focus}
				isUrl
			/>
			<Icon
				class="absolute inset-0 size-full opacity-0 fxs-image-button__bg--active"
				name={props.imageData.active ?? props.imageData.focus}
				isUrl
			/>
			<Icon
				class="absolute inset-0 size-full opacity-0 fxs-image-button__bg--disabled"
				name={props.imageData.disabled ?? props.imageData.base}
				isUrl
			/>
		</Activatable>
	);
};

/**
 * An Image Button component.
 * A simple activatable button that allows the user to pass in custom image to represent the button
 * ```tsx
 * // Example - Simple image button
 * <ImageButton
 * 	imageData={
 * 		base: "url(blp:button_image_base.png)",
 * 		focus: "url(blp:button_image_focus.png)"
 * 	}
 * 	size="6"
 * 	onActivate={() => console.log("activated")} />
 * ```
 * Default implementation: {@link ImageButtonComponent} Based on: {@link Activatable}
 * @param imageData If no disabled or active images are provided, will fall back to using base (at 50% opacity) and focus images respectively
 * @param size Defaults to `12`
 * @param {ActivatableProps} props See {@link ActivatableProps} for a full list of properties
 *
 * Commonly Used Properties:
 * @param {boolean} props.disabled Is this control disabled both visually and for input? Default: false
 * @param {string} props.hotkeyAction The name of a hotkey action which activates this component. Default: undefined
 * @param {string} props.name The name of the component set as the data-name property - useful for debugging or searching the DOM tree. Default: "Activatable"
 * @param {() => void} props.onActivate Event which triggers when the control is activated either through hotkey, mouse click, touch, or other user interaction. Default: undefined
 */
export const ImageButton = ComponentRegistry.register({
	name: "ImageButton",
	createInstance: ImageButtonComponent,
});
